<template><v-container class="py-8" style="max-width:520px"><v-card outlined class="pa-6"><h1 class="text-h5 mb-4">Accept your invitation</h1><v-alert v-if="error" type="error">{{ error }}</v-alert><v-alert v-if="complete" type="success">Your account is ready. <router-link to="/account">Sign in</router-link> to continue.</v-alert><v-form v-else @submit.prevent="accept"><p>Enter the single-use token from your invitation email and choose a password.</p><v-text-field v-model="token" label="Invitation token" outlined autocomplete="off"/><v-text-field v-model="password" label="New password" type="password" autocomplete="new-password" outlined hint="At least 8 characters" persistent-hint/><v-btn type="submit" color="primary" class="mt-4" :loading="busy" :disabled="!token || password.length<8">Activate account</v-btn></v-form><template v-if="!complete"><p class="mt-6">Or continue with GitHub or ORCID below, then choose “I have an invitation” and enter your token to claim your existing account.</p><provider-login/></template></v-card></v-container></template>
<script>
import axios from 'axios';
import ProviderLogin from './ProviderLogin.vue';
import {apiBase, errorMessage} from '../../http';
export default {name: 'Invitation', components: {ProviderLogin}, data: () => ({token: '', password: '', error: '', busy: false, complete: false}), beforeDestroy() { this.token = ''; this.password = ''; }, methods: {async accept() { this.busy = true; this.error = ''; try { await axios.post(apiBase + '/api/v1/auth/invitations/accept', {token: this.token.trim(), password: this.password}); this.token = ''; this.password = ''; this.complete = true; } catch (error) { this.error = errorMessage(error); } finally { this.busy = false; } }}};
</script>
